"""把教学修订写成可审核的数据；不触碰前后测或数据库。"""
import json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
sys.path.insert(0,str(ROOT/'videos/course-series'))
from content import lessons as videos
video={l['number']:l for l in videos}
original=json.loads((ROOT/'backups/curriculum-20260912/effective-lessons.json').read_text(encoding='utf-8'))
revised=json.loads(json.dumps(original,ensure_ascii=False))

def variant(title,change,text,answer,explain):
    return dict(title=title,change=change,text=text,answer=answer,explain=explain)
def practice(text,answer,explain,topic,svg=''):
    return dict(text=text,answer=str(answer),explain=explain,topic=topic,svg=svg,version='2026-09-r2')
def update(n,**fields): revised[n-1]['detail'].update(fields)
def set_practice(n,rows): revised[n-1]['practice']=[practice(*r) for r in rows]
def video_problem(n):
    return video[n]['scenes'][0]['data']['stem']

# 第一课保留已认可的成片与三道练习；网上的第二变式改为整体配套衔接。
d=revised[0]['detail']
d['variants'][1]=variant('变式2 · 先看所求能否配套','从求单价改为求一大一小的组合，先观察整体。','同型大、小积木重量分别固定。2个大积木和3个小积木重23克，3个大积木和2个小积木重22克。1个大积木和1个小积木合重多少克？','9克。','两组相加是5大5小共45克，即5套，每套45÷5＝9克。不必先求单个重量。下一课将比较两边调整与整体求值的适用条件。')
d['transfer']=[d['variants'][1]['text'],d['variants'][1]['answer'],d['variants'][1]['explain']]
d['exit']='能解释直接消去与配成一套的理由；遇到需要同时调整两行的题，先列条件，把方法选择留到下一课深化。'

revised[1].update(title=video[2]['title'],goal='当两行都没有相同数量时，选择调整对象；根据最终所求比较消去与整体法。',prereq='第一课的直接消去、配成一套；整数乘除，不要求预先学过公倍数。',pitfall='只调整一种数量，漏乘总重量；不看所求，把不同数量的组合误当成相同套数。')
update(2,
 mother=dict(title='两种零件，如何选择比较方法？',text=video_problem(2),asks=['用两行都调整的方法求出单个重量。','换一种消去对象检查结果；解释每个乘数为何这样选。'],answer='大零件8克，小零件5克。',explain='上行×3得6大9小93克；下行×2得6大4小68克。差25克对应5小，小5克，大(31−15)÷2＝8克。也可上×2、下×3消去6小，差40克对应5大。'),
 hook='先圈出两行的数量：2大3小、3大2小。两种数量都不同，这次不能直接消去。我们要让两行一起变化，再比较不同方法。',
 check=['两个一组能变成哪些数量？三个一组呢？｜2、4、6……与3、6……，都能变成6。','把一份材料取3份，哪些量要一起变化？｜大、小零件数与总重量都乘3。'],
 concept='整份等量关系可以同时扩大；造出相同数量后，重量差才只对应另一种零件。所求若与合并后的组合成比例，也可先求一套，不必分别求单个。',
 steps=[['完整列条件与所求','用两列表示大、小零件，一列表示总重；先确认两种单个重量都固定。','2大＋3小＝31；3大＋2小＝34'],['两行都调整','2个一组取3份、3个一组取2份，都有6大；整行乘，不漏数量或重量。','上×3：6大9小93；下×2：6大4小68'],['差量对应差重','93−68的25克对应9−4的5小；除以5得到一个小零件，再代回求大。','小5克；大(31−3×5)÷2＝8克'],['比较路线并检查','改为消去小零件，可上×2、下×3。两种路线都得到大8小5，再核对两个原条件。','2×8＋3×5＝31；3×8＋2×5＝34']],
 variants=[variant('变式1 · 所求从单个变成相同组合','合并后能配成相同套数，先考虑整体法。',video[2]['scenes'][4]['data']['stem'],'60克。','两行合并5大5小75克，一套15克，4套60克。'),variant('变式2 · 组合数量不再相同','先借助整体，再补出目标；不能把不同比例当同一套。',video[2]['scenes'][-1]['data']['stem'],'64克。',video[2]['challengeAnswer'])],
 questions=[['为什么这次两行都要调整？','2与3都能通过整份倍乘变成6，原来的任何一行都没有6个。'],['消去大零件和小零件，结果应一样吗？','应一样；都是同一组原条件，分别求得大8克、小5克。'],['5长4短能直接算成几套一长一短吗？','不能。可以从5套减去1个短块，或先求单个重量。']],
 repair='若把34−31当单个重量，让学生写清相减同时多1大、少1小。若漏乘，用“取3份”逐列检查。若把目标强行配套，画出多出来的那一个。',
 board='原条件 → 选对象 → 两行整份调整 → 差量对应差重 → 代回；先看所求，能配套时考虑整体。',
 opening='大家好，今天这两行没有相同的数量。我先说明想消去哪一种，再把两行都调整到同样多。',
 talk=['已知____与____，要求____；直接相减还会留下____。','我选____，把上行乘____、下行乘____，所有数量和重量都一起变。','差____克对应____个，所以____；换另一个消去对象也得到____。','所求是____，我选择消去／整体法，因为____；检查原条件____。'],
 sample='两行的大零件分别2个、3个，我让它们都变成6个：上行取3份、下行取2份。重量相差25克，小零件相差5个，所以每小5克。再求每大8克。若题目只问相同比例的一套，我还会先看能否把两行合并。',
 labTask='选择先对齐大零件或小零件，逐步观察两行数量与重量一起变化。先预测抵消以后剩下几个，再看结果。',
 exit='不靠提示选择一种对齐路线，并说明整体法什么时候适用；能独立完成新组合题。')
update(2,transfer=[revised[1]['detail']['variants'][1][k] for k in ('text','answer','explain')])

