update(4,variants=[variant('变式1 · 平方数出现中间重合','不再只换总数，重点观察同一个因数如何去重。',video[4]['scenes'][-3]['data']['stem'],'9种，因数1、2、3、4、6、9、12、18、36。','1×36、2×18、3×12、4×9、6×6；6只记一次，4×2＋1＝9。'),variant('变式2 · 给因数增加范围限制','先找全，再按至少与至多筛选。',video[4]['scenes'][-1]['data']['stem'],'每袋6、8、12个，共3种。',video[4]['challengeAnswer'])],transfer=[video[4]['scenes'][-1]['data']['stem'],'6、8、12个，共3种。',video[4]['challengeAnswer']],exit='能成对找全因数，解释平方数中间因数只算一次，并按范围筛选。')

